/* Admin presentation only. Existing task mutations and permission checks remain authoritative. */
(function(){
'use strict';
const tx=(ar,en)=>L==='ar'?ar:en, e=v=>AdvaconUI.escape(String(v??''));
const flow={q:'',project:'',assignee:'',alert:'',section:'board'};
window.adminRecentlyDone=r=>r.effStatus==='Complete'&&!!r.confirmedAt&&Date.now()-new Date(r.confirmedAt).getTime()>=0&&Date.now()-new Date(r.confirmedAt).getTime()<8*3600000;
const live=r=>!isAdminArchived(r)&&!r.archived&&r.effStatus!=='Complete';
const alerts=()=>[['overdue',tx('متأخرة','Overdue')],['ready',tx('حان موعد البدء','Ready to start')],['pending',tx('بانتظار تأكيدك','Awaiting confirmation')],['materials',tx('مواد تحتاج إجراء','Materials need action')]];
function alertMatches(r,key){if(!key)return true;if(!live(r))return false;return key==='overdue'?isOpen(r)&&!r.pendingConfirm&&r.effStatus==='Overdue':key==='ready'?!!r.isReady:key==='pending'?!!r.pendingConfirm:key==='incoming'?isIncoming(r):key==='open'?isOpen(r)&&!r.pendingConfirm:key==='materials'?['pending','allocated'].includes(state.mrBadges?.[String(r.id)]?.status):false;}
function flowBase(){return state.requests.map(calc).filter(r=>(live(r)||adminRecentlyDone(r))&&(!flow.project||r.project===flow.project)&&(!flow.assignee||r.assignedTo===flow.assignee)&&[r.title,r.requestedBy,r.assignedTo,fmtID(r.id)].join(' ').toLowerCase().includes(flow.q.trim().toLowerCase()));}
window.adminFlowRows=()=>flowBase().filter(r=>alertMatches(r,flow.alert));
function flowHash(){const p=new URLSearchParams();if(flow.alert)p.set('alert',flow.alert);if(flow.project)p.set('project',flow.project);if(flow.assignee)p.set('assignee',flow.assignee);return '#manage'+(p.size?'?'+p:'');}
window.adminFlowSet=function(key,value){if(!['project','assignee','alert'].includes(key))return;flow[key]=value;history.replaceState(history.state,'',flowHash());render();};
window.adminFlowSearch=function(input){flow.q=input.value;flowRenderResults();};
function flowAlerts(){const rows=flowBase(),counts=alerts().map(([key,label])=>[key,label,rows.filter(r=>alertMatches(r,key)).length]);return `<section class="flow-alerts" aria-label="${tx('تنبيهات الطلبات','Request alerts')}">${counts.some(x=>x[2])?counts.filter(x=>x[2]>0).map(([key,label,n])=>`<button class="flow-alert ${key}" aria-pressed="${flow.alert===key}" onclick="adminFlowSet('alert','${key}')"><span>${label}</span><strong>${n}</strong></button>`).join(''):`<p class="flow-calm">${tx('لا توجد تنبيهات تحتاج إجراء ضمن البحث الحالي','No alerts need action in the current search')}</p>`}</section>${flow.alert?`<div class="flow-filter-state" role="status">${tx('تعرض الآن','Showing')}: ${e(Object.fromEntries(alerts())[flow.alert]||({incoming:tx('الواردة','Incoming'),open:tx('المسندة الجارية','Current assigned tasks')})[flow.alert]||'')} <button class="btn sec" onclick="adminFlowSet('alert','')">${tx('إظهار المهام الجارية','Show current tasks')}</button></div>`:''}`;}
function flowRenderResults(){const area=document.getElementById('flow-board-area'),strip=document.getElementById('flow-alert-area');if(!area)return;if(strip)strip.innerHTML=flowAlerts();area.classList.toggle('flow-filtered',!!(flow.alert||flow.q));area.innerHTML=viewManage();AdvaconUI.enhance(area);}
window.adminMaterialBadge=function(r){const b=state.mrBadges?.[String(r.id)];if(!b)return '';const labels={pending:tx('مواد بانتظار التجهيز','Materials awaiting preparation'),allocated:tx('مواد جاهزة للتسليم','Materials ready for handover'),issued:tx('تم صرف المواد','Materials issued'),rejected:tx('طلب مواد مرفوض','Material request declined'),cancelled:tx('طلب مواد ملغى','Material request cancelled')};return `<div class="mc-mrbadge"><span class="team-status ${b.status==='pending'?'pending':b.status==='allocated'?'ready':''}">${e(labels[b.status]||b.status)} · ${e(b.lines_count??0)}</span></div>`;};
window.adminScheduleBadge=function(r){if(!r.isFuture&&!r.isReady)return '';const remaining=Math.max(1,Math.ceil((new Date(r.schedStart).getTime()-Date.now())/60000)),relative=remaining>=1440?Math.ceil(remaining/1440)+' '+tx('يوم','days'):remaining>=60?Math.ceil(remaining/60)+' '+tx('ساعة','hours'):remaining+' '+tx('دقيقة','minutes');return `<div class="flow-schedule ${r.isFuture?'future':'ready'}"><strong>${r.isFuture?tx('مجدولة للمستقبل','Scheduled ahead'):tx('حان موعد البدء','Ready to start')}</strong><span>${e(wpDate(r.schedStart))} · ${tx('بتوقيت الرياض','Riyadh time')}</span><small>${r.isFuture?tx('تبدأ خلال ','Starts in ')+relative:tx('بانتظار بدء الفني؛ لم يبدأ التنفيذ بعد','Waiting for the technician; work has not started')}</small></div>`;};
window.adminWorkView=function(){manageView='cards';const options=(arr,value)=>arr.map(x=>`<option value="${e(x)}" ${value===x?'selected':''}>${e(x)}</option>`).join('');if(flow.section==='period')return `<div class="phead phead-row"><h1>${tx('المهام الدورية — القوالب','Recurring task templates')}</h1><button class="btn sec" onclick="go('manage')">${tx('العودة للطلبات','Back to requests')}</button></div>`+viewPeriodTasks();return `<div class="phead phead-row"><div><h1>${tx('الطلبات','Requests')}</h1><p>${tx('الموافقة تشمل إسناد الطلب للفني. تابع العمل ونفّذ الإجراء من بطاقته.','Approval includes assigning a technician. Follow the work and act directly from its card.')}</p></div><button class="btn" onclick="openAddTask()">＋ ${tx('إضافة طلب','Add request')}</button></div><div class="filterbar flow-toolbar"><input type="search" aria-label="${tx('بحث الطلبات الجارية','Search current requests')}" placeholder="${tx('رقم الطلب أو العنوان أو الفني','Request ID, title or technician')}" value="${e(flow.q)}" oninput="adminFlowSearch(this)"><select aria-label="${tx('المشروع','Project')}" onchange="adminFlowSet('project',this.value)"><option value="">${tx('كل المشاريع','All projects')}</option>${options(state.lists.projects,flow.project)}</select><select aria-label="${tx('الفني','Technician')}" onchange="adminFlowSet('assignee',this.value)"><option value="">${tx('كل الفنيين','All technicians')}</option>${options(filterStaffNames(),flow.assignee)}</select><button class="btn sec" onclick="go('media')">${tx('الصور والملفات','Images & files')}</button></div><div id="flow-alert-area">${flowAlerts()}</div><div id="flow-board-area" class="${flow.alert||flow.q?'flow-filtered':''}">${viewManage()}</div>`;};
let detail=null;
window.adminCloseDetail=()=>detail?.close();
const work={stage:'all',layout:'table',section:'tasks',q:'',project:'',assignee:'',status:'',page:1};
const stages=()=>[['all',tx('الكل','All')],['incoming',tx('جديدة','New')],['open',tx('قيد المعالجة','In progress')],['assigned',tx('كل المسند الجاري','All current assignments')],['pending',tx('بانتظار التأكيد','Awaiting confirmation')],['complete',tx('مكتملة','Completed')],['cancelled',tx('ملغاة / مرفوضة','Cancelled / declined')],['overdue',tx('متأخرة','Overdue')]];
window.adminTaskStage=r=>isAdminArchived(r)?'cancelled':r.effStatus==='Complete'?'complete':r.pendingConfirm?'pending':!r.accepted?'incoming':'open';
const matches=(r,key)=>key==='all'||(key==='assigned'?['open','pending'].includes(adminTaskStage(r)):(key==='overdue'?adminTaskStage(r)==='open'&&r.effStatus==='Overdue':adminTaskStage(r)===key));
window.adminWorkRows=()=>byNumberDesc(state.requests.map(calc).filter(r=>matches(r,work.stage)&&(!work.status||r.effStatus===work.status)&&(!work.project||r.project===work.project)&&(!work.assignee||r.assignedTo===work.assignee)&&[r.title,r.requestedBy,r.assignedTo,r.notes,fmtID(r.id)].join(' ').toLowerCase().includes(work.q.trim().toLowerCase())));
function workHash(){const q=new URLSearchParams({stage:work.stage,view:work.layout,section:work.section});if(work.status)q.set('status',work.status);if(work.project)q.set('project',work.project);if(work.assignee)q.set('assignee',work.assignee);if(work.page>1)q.set('page',work.page);for(const key of Object.keys(registerDefaults))if(work[key])q.set(key,work[key]);return 'all?'+q;}
window.adminResolveRoute=function(raw){const [route,query='']=raw.split('?'),p=new URLSearchParams(query);
 if(route==='manage'||route==='open'){
  if(['complete','cancelled'].includes(p.get('stage')))return adminResolveRoute('all?'+p);
  flow.section=p.get('section')==='period'?'period':'board';flow.alert=['overdue','ready','pending','materials','incoming','open'].includes(p.get('alert')||p.get('stage'))?(p.get('alert')||p.get('stage')):'';flow.project=p.get('project')||'';flow.assignee=p.get('assignee')||'';return 'manage';
 }
 if(['all','archive'].includes(route)){work.stage=route==='archive'?'cancelled':p.get('stage')||'all';if(!stages().some(x=>x[0]===work.stage))work.stage='all';work.layout=p.get('view')==='board'?'board':'table';work.section='tasks';for(const key of Object.keys(registerDefaults))work[key]=p.get(key)??registerDefaults[key];if(!dateNames()[work.dateBy])work.dateBy='received';if(!['newest','oldest','project','closed'].includes(work.sort))work.sort='newest';if(!selectedColumns().length)work.columns=registerDefaults.columns;work.status=p.get('status')||'';work.project=p.get('project')||'';work.assignee=p.get('assignee')||'';work.page=Math.max(1,Number(p.get('page'))||1);return 'all';}return route;};
window.adminSetWork=function(key,value){work[key]=value;if(key!=='page')work.page=1;history.replaceState(history.state,'','#'+workHash());render();};
window.adminQueue=function(key){if(state.role!=='admin')return;flow.q='';go('manage?alert='+encodeURIComponent(key));};
const taskLink=(r)=>`<button class="ad-title-button" data-request-id="${Number(r.id)}" onclick="adminDetail(${Number(r.id)})">${e(r.title)}</button>`;
window.adminTaskLink=taskLink;
window.adminTeamTabs=()=>'';
const teamView={q:'',filter:'all'};
const teamLabels=()=>({all:tx('كل العمل القائم','All current work'),working:tx('قيد التنفيذ','In progress'),scheduled:tx('مجدولة للمستقبل','Scheduled ahead'),ready:tx('لم تبدأ / حان موعدها','Not started / ready'),pending:tx('بانتظار التأكيد','Awaiting confirmation'),held:tx('معلّقة / تحتاج مراجعة','On hold / needs review'),overdue:tx('متأخرة','Overdue')});
window.adminTeamBucket=r=>adminTaskStage(r)==='pending'?'pending':adminTaskStage(r)!=='open'?null:r.isFuture?'scheduled':['On Hold','Needs Review','Needs Update'].includes(r.status)?'held':r.status==='In Progress'?'working':'ready';
const teamMatch=(r,filter)=>filter==='all'||(filter==='overdue'?adminTaskStage(r)==='open'&&r.effStatus==='Overdue':adminTeamBucket(r)===filter);
function teamEntries(){
 const grouped=new Map();state.requests.map(calc).forEach(r=>{if(!adminTeamBucket(r))return;const assignee=(r.assignedTo||'').trim();if(!assignee)return;if(!grouped.has(assignee))grouped.set(assignee,[]);grouped.get(assignee).push(r);});
 const staff=staffList(),known=new Set(staff.map(x=>(x.en||'').trim()));
 return staff.map(s=>({key:'s:'+s.id,label:staffDisp(s.en),search:[s.ar,s.en].join(' '),inactive:!staffActive(s),missing:false,tasks:grouped.get((s.en||'').trim())||[]})).concat([...grouped].filter(([key])=>!known.has(key)).map(([key,tasks])=>({key:'o:'+key,label:key,search:key,inactive:false,missing:true,tasks}))).sort((a,b)=>Number(a.inactive)-Number(b.inactive)||b.tasks.filter(r=>teamMatch(r,'overdue')).length-a.tasks.filter(r=>teamMatch(r,'overdue')).length||a.label.localeCompare(b.label,L==='ar'?'ar':'en'));
}
function teamTask(r){const bucket=adminTeamBucket(r),labels=teamLabels();return `<article class="team-task"><div class="team-task-top"><span>${e(fmtID(r.id))}</span><span class="team-status ${bucket}">${e(labels[bucket])}</span></div><h3>${taskLink(r)}</h3><p>${e(r.project||tx('المشروع غير محدد','Project not specified'))}</p>${r.schedStart?`<p class="team-schedule">${tx('موعد البدء','Scheduled start')}: <b>${e(wpDate(r.schedStart))}</b></p>`:''}${r.isReady?`<p class="team-due">${tx('حان موعد البدء؛ بانتظار بدء الفني','Start time reached; waiting for technician')}</p>`:''}${teamMatch(r,'overdue')?`<p class="ad-overdue">${tx('متأخرة عن موعد الإنجاز','Past the completion deadline')}${Number.isFinite(r.daysleft)?' · '+Math.abs(r.daysleft)+' '+tx('يوم','days'):''}</p>`:''}${r.due?`<p>${tx('موعد الإنجاز','Due')}: ${e(r.due)}</p>`:''}${r.recurringId?`<span class="team-status">${tx('مهمة دورية','Recurring task')}</span>`:''}<div class="btnrow"><button class="btn sec" onclick="adminDetail(${Number(r.id)})">${tx('فتح الطلب وإجراءاته','Open request & actions')}</button></div></article>`;}
function teamResults(){
 const entries=teamEntries().filter(x=>x.search.toLowerCase().includes(teamView.q.trim().toLowerCase())&&(teamView.filter==='all'||x.tasks.some(r=>teamMatch(r,teamView.filter)))),labels=teamLabels();
 return `<p class="ad-muted" role="status">${entries.length} ${tx('موظف مطابق','matching staff')} · ${e(labels[teamView.filter])}</p>`+(entries.length?`<div class="team-members">${entries.map(member=>{const rows=member.tasks.filter(r=>teamMatch(r,teamView.filter)).sort((a,b)=>Number(teamMatch(b,'overdue'))-Number(teamMatch(a,'overdue'))||(new Date(a.schedStart||0)-new Date(b.schedStart||0))||b.id-a.id),open=!!state.ttOpen?.[member.key];return `<section class="team-member"><button class="team-member-head" aria-expanded="${open}" onclick="ttToggle('${encodeURIComponent(member.key).replace(/'/g,'%27')}')"><span class="team-avatar" aria-hidden="true">${e(member.label.slice(0,1))}</span><span class="team-member-name"><strong>${e(member.label)}</strong><small>${member.missing?tx('الاسم غير مرتبط بسجل موظف حالي','Name not linked to a current staff record'):member.inactive?tx('حساب معطّل','Inactive account'):member.tasks.length?tx('لديه مهام قائمة','Has current assignments'):tx('لا توجد مهام قائمة مسندة','No current assignments')}</small></span><span class="team-member-count">${member.tasks.length} ${tx('مهمة','tasks')}</span><span aria-hidden="true">${open?'−':'+'}</span></button><div class="team-member-summary">${['working','scheduled','ready','pending','held'].map(key=>{const n=member.tasks.filter(r=>adminTeamBucket(r)===key).length;return n?`<span class="team-status ${key}">${labels[key]} <b>${n}</b></span>`:'';}).join('')}${member.tasks.some(r=>teamMatch(r,'overdue'))?`<span class="team-status late">${labels.overdue} <b>${member.tasks.filter(r=>teamMatch(r,'overdue')).length}</b></span>`:''}</div>${open?`<div class="team-member-body">${rows.length?rows.map(teamTask).join(''):`<p class="empty">${tx('لا توجد مهام مطابقة','No matching assignments')}</p>`}</div>`:''}</section>`;}).join('')}</div>`:`<div class="empty">${tx('لا يوجد موظف يطابق البحث والفلتر.','No staff match the search and filter.')}</div>`);
}
window.adminTeamFilter=function(value){if(!Object.hasOwn(teamLabels(),value))return;teamView.filter=value;render();};
window.adminTeamSearch=function(input){teamView.q=input.value;const host=document.getElementById('team-results');host.innerHTML=teamResults();AdvaconUI.enhance(host);};
window.adminTeamView=function(){const entries=teamEntries(),tasks=entries.flatMap(x=>x.tasks),labels=teamLabels();return `<div class="ad-welcome"><div><h1>${tx('متابعة الفريق','Team workload')}</h1><p>${tx('اعرف من يعمل الآن، ومن لديه مهام مستقبلية، وما يحتاج متابعة.','See current work, future assignments and what needs follow-up.')}</p></div></div><div class="team-overview">${['working','scheduled','ready','pending','overdue'].map(key=>`<button class="team-metric ${key}" aria-pressed="${teamView.filter===key}" onclick="adminTeamFilter('${key}')"><span>${labels[key]}</span><strong>${tasks.filter(r=>teamMatch(r,key)).length}</strong></button>`).join('')}</div><p class="ad-muted">${tx('الأعداد للمهام المسندة القائمة. المتأخرة قد تتداخل مع حالات التنفيذ؛ المجدولة ليست عملًا بدأ فعليًا.','Counts cover current assigned tasks. Overdue can overlap execution states; scheduled work has not started.')}</p><div class="filterbar"><input type="search" aria-label="${tx('البحث عن موظف','Search staff')}" placeholder="${tx('اسم الموظف بالعربية أو الإنجليزية','Staff name in Arabic or English')}" value="${e(teamView.q)}" oninput="adminTeamSearch(this)"><select aria-label="${tx('فلتر مهام الفريق','Team task filter')}" onchange="adminTeamFilter(this.value)">${Object.entries(labels).map(([key,label])=>`<option value="${key}" ${teamView.filter===key?'selected':''}>${label}</option>`).join('')}</select><button class="btn sec" onclick="adminTeamFilter('all')">${tx('كل العمل القائم','All current work')}</button></div><div id="team-results">${teamResults()}</div>`;};
function resultHTML(){return registryResults();}
function legacyResultHTML(){const all=adminWorkRows(),max=Math.max(1,Math.ceil(all.length/40));work.page=Math.min(work.page,max);const rows=all.slice((work.page-1)*40,work.page*40),labels=Object.fromEntries(stages());const status=r=>`<span class="count-chip">${e(labels[adminTaskStage(r)])}</span>`;
 const cards=list=>list.map(r=>`<article class="mcard"><div class="mc-top"><span class="mc-id">${e(fmtID(r.id))}</span>${status(r)}</div><div class="mc-title">${taskLink(r)}</div><p>${e(r.project||'—')} · ${e(r.assignedTo||tx('غير مسند','Unassigned'))}</p>${r.effStatus==='Overdue'&&adminTaskStage(r)==='open'?`<p class="ad-overdue">${tx('متأخرة','Overdue')}</p>`:''}<div class="mc-acts"><button class="btn sec" onclick="adminDetail(${Number(r.id)})">${tx('التفاصيل والإجراءات','Details & actions')}</button></div></article>`).join('');
 const table=`<div class="tbl-wrap"><table class="tbl"><thead><tr>${[tx('رقم الطلب','Request ID'),tx('الطلب','Request'),tx('المشروع','Project'),tx('الفني','Technician'),tx('المرحلة','Stage'),tx('الاستحقاق','Due')].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${e(fmtID(r.id))}</td><td>${taskLink(r)}</td><td>${e(r.project||'—')}</td><td>${e(r.assignedTo||'—')}</td><td>${status(r)}</td><td>${e(r.due||'—')}</td></tr>`).join('')}</tbody></table></div>`;
 const board=`<div class="ad-work-board">${stages().filter(([key])=>!['all','overdue'].includes(key)).map(([key,label])=>{const items=rows.filter(r=>adminTaskStage(r)===key);return items.length?`<section class="mcol"><h3 class="mcol-head">${label} · ${items.length}</h3>${cards(items)}</section>`:'';}).join('')}</div>`;
 return `<p class="ad-muted" role="status">${all.length} ${tx('طلب مطابق','matching requests')} · ${tx('صفحة','Page')} ${work.page}/${max}</p>`+(rows.length?(work.layout==='board'?board:table):`<div class="empty">${tx('لا توجد طلبات تطابق الفلاتر','No requests match these filters')}</div>`)+`<div class="btnrow"><button class="btn sec" ${work.page<=1?'disabled':''} onclick="adminSetWork('page',${work.page-1})">${tx('السابق','Previous')}</button><button class="btn sec" ${work.page>=max?'disabled':''} onclick="adminSetWork('page',${work.page+1})">${tx('التالي','Next')}</button></div>`;
}
window.adminWorkSearch=function(input){work.q=input.value;work.page=1;const el=document.getElementById('ad-work-results');el.innerHTML=resultHTML();AdvaconUI.enhance(el);};
window.adminRequestTabs=function(){return `<div class="ad-tabs">${[['manage',tx('الطلبات','Requests')],['manage?section=period',tx('المهام الدورية','Recurring templates')],['media',tx('الصور والملفات','Images & files')]].map(([route,label])=>`<button onclick="go('${route}')" aria-selected="${route==='media'?state.route==='media':route.includes('period')?state.route==='manage'&&work.section==='period':state.route==='manage'&&work.section==='tasks'}">${label}</button>`).join('')}</div>`;};
window.adminRegistryView=function(){const header=`<div class="phead phead-row"><h1>${tx('سجل الطلبات','Request register')}</h1></div>`;if(work.section==='period')return header+viewPeriodTasks();const rows=state.requests.map(calc);const options=(arr,value)=>arr.map(x=>`<option value="${e(x)}" ${value===x?'selected':''}>${e(x)}</option>`).join('');return header+`<div class="ad-tabs ad-work-stages">${stages().map(([key,label])=>`<button aria-selected="${work.stage===key}" onclick="adminSetWork('stage','${key}')">${label} <b>${rows.filter(r=>matches(r,key)).length}</b></button>`).join('')}</div><p class="ad-muted">${tx('المتأخرة فلتر ضمن قيد المعالجة؛ لا تُجمع مع المراحل. الأعداد لكل الطلبات، والنتائج أدناه حسب البحث.','Overdue is a subset of in progress, not an additional stage. Stage counts cover all requests; results below follow your filters.')}</p><div class="filterbar"><input type="search" aria-label="${tx('بحث الطلبات','Search requests')}" placeholder="${tx('رقم الطلب أو العنوان أو الفني','Request ID, title or technician')}" value="${e(work.q)}" oninput="adminWorkSearch(this)"><select aria-label="${tx('المشروع','Project')}" onchange="adminSetWork('project',this.value)"><option value="">${tx('كل المشاريع','All projects')}</option>${options(state.lists.projects,work.project)}</select><select aria-label="${tx('الفني','Technician')}" onchange="adminSetWork('assignee',this.value)"><option value="">${tx('كل الفنيين','All technicians')}</option>${options(filterStaffNames(),work.assignee)}</select><select aria-label="${tx('حالة التنفيذ','Execution status')}" onchange="adminSetWork('status',this.value)"><option value="">${tx('كل حالات التنفيذ','All execution statuses')}</option>${options(state.lists.statuses,work.status)}</select><select aria-label="${tx('طريقة العرض','View')}" onchange="adminSetWork('layout',this.value)"><option value="table" ${work.layout==='table'?'selected':''}>${tx('جدول','Table')}</option><option value="board" ${work.layout==='board'?'selected':''}>${tx('لوحة','Board')}</option></select><button class="btn sec" onclick="exportExcel('work')">${tx('تصدير النتائج','Export results')}</button></div><div id="ad-work-results">${resultHTML()}</div>`;};
window.adminHome=function(){
 const rows=state.requests.map(calc),incoming=rows.filter(r=>matches(r,'incoming')),pending=rows.filter(r=>matches(r,'pending')),overdue=rows.filter(r=>matches(r,'overdue')),working=rows.filter(r=>matches(r,'open'));
 const metric=(title,n,key,kind='')=>`<button class="ad-metric ${kind}" onclick="adminQueue('${key}')"><span>${title}</span><strong>${n}</strong><small>${tx('عرض الطلبات ←','View requests →')}</small></button>`;
 return `<header class="ad-welcome"><div><span class="eyebrow">ADVACON / ${tx('الإدارة','ADMINISTRATION')}</span><h1>${tx('متابعة العمل تبدأ من هنا','Your work, at a glance')}</h1><p>${tx('الطلبات التي تحتاج قرارك، ومتابعة سير العمل.','Review requests that need a decision and follow work in progress.')}</p></div><button class="btn" onclick="openAddTask()">＋ ${tx('إضافة طلب','Add request')}</button></header>
 <div class="ad-metrics">${metric(tx('طلبات جديدة','New requests'),incoming.length,'incoming')}${metric(tx('بانتظار تأكيدك','Awaiting confirmation'),pending.length,'pending')}${metric(tx('مهام متأخرة','Overdue tasks'),overdue.length,'overdue','ad-warn')}${metric(tx('مهام مفتوحة','Open tasks'),working.length,'open')}</div>
 <div class="ad-home-grid"><section class="ad-surface"><div class="ad-section-head"><div><h2>${tx('أولوية المتابعة','Follow up first')}</h2><p>${tx('بانتظار التأكيد، ثم المتأخرة، ثم الجديدة','Awaiting confirmation, then overdue, then new')}</p></div><button class="btn sec" onclick="go('manage')">${tx('كل الطلبات','Manage requests')}</button></div><div id="ad-followup">${homeRows([...new Map([...pending,...overdue,...incoming].map(r=>[r.id,r])).values()].slice(0,8))}</div></section>
 <aside class="ad-surface"><h2>${tx('مساحات العمل','Workspaces')}</h2><p class="ad-muted">${tx('انتقل مباشرة إلى القسم المطلوب','Go directly to your workspace')}</p><div class="ad-links"><a href="/warehouse?from=admin">${tx('المستودعات','Warehouses')} <span>←</span></a><a href="/housing?from=admin">${tx('الإسكان','Housing')} <span>←</span></a><button onclick="go('techtasks')">${tx('متابعة الفريق','Team workload')} <span>←</span></button><button onclick="go('reports')">${tx('التقارير والإحصاءات','Reports & statistics')} <span>←</span></button></div></aside></div><div id="ad-decisions"></div>`;
};
function homeRows(rows){return rows.length?rows.map(r=>`<button class="ad-request" onclick="adminDetail(${Number(r.id)})"><span class="ad-request-id">${e(fmtID(r.id))}</span><span class="ad-request-title"><b>${e(r.title)}</b><small>${e(r.project||'—')} · ${e(r.assignedTo||tx('غير مسند','Unassigned'))}</small></span><span>${r.pendingConfirm?e(tx('بانتظار التأكيد','Awaiting confirmation')):stBadge(r.effStatus)}</span><span aria-hidden="true">←</span></button>`).join(''):`<div class="empty">${tx('لا توجد طلبات تحتاج متابعة عاجلة في البيانات الحالية.','No requests need urgent follow-up in the current data.')}</div>`;}
window.adminDetail=function(id,initialTab=0){
 const r=state.requests.map(calc).find(x=>x.id===id);if(!r||state.role!=='admin')return;
 if(detail)detail.close();
 const baseRoute=location.hash.split('?')[0]||'#manage',parameters=new URLSearchParams(location.hash.split('?')[1]||'');parameters.delete('task');parameters.delete('pane');const returnHash=baseRoute+(parameters.size?'?'+parameters:'');parameters.set('task',String(id));parameters.set('pane',String(initialTab));history.replaceState(history.state,'',baseRoute+'?'+parameters);
 const body=document.createElement('div');body.className='ad-detail';
 const tabs=document.createElement('div');tabs.className='ad-tabs';tabs.setAttribute('role','tablist');
 const panel=document.createElement('div');panel.className='ad-detail-content';panel.setAttribute('role','tabpanel');
 const actionbar=document.createElement('div');actionbar.className='ad-detail-actions';
 const add=(label,fn)=>{const b=document.createElement('button');b.className='btn sec';b.textContent=label;b.onclick=()=>{detail.close();detail=null;fn();};actionbar.append(b);};
 if(isIncoming(r)){add(tx('قبول الطلب','Accept request'),()=>acceptReq(id));add(tx('رفض الطلب','Decline request'),()=>askReject(id));}
 else if(r.pendingConfirm&&!isArchived(r)){add(tx('تأكيد الإنجاز','Confirm completion'),()=>confirmStaffDone(id));add(tx('إرجاع للفني','Return to technician'),()=>returnStaffTask(id));add(tx('تعديل إثبات الإنجاز','Edit completion evidence'),()=>openCloseoutEdit(id));}
 else if(isOpen(r)){add(tx('إغلاق المهمة','Close task'),()=>askClose(id));}
 add(tx('تعديل وإسناد','Edit & assign'),()=>openEdit(id));
 if(isAdminArchived(r))add(tx('استعادة الطلب','Restore request'),()=>restoreTask(id));
 if(r.effStatus==='Complete')add(tx('إعادة فتح المهمة','Reopen task'),()=>reopenTask(id));
 if(isAccepted(r)&&!r.pendingConfirm&&r.effStatus!=='Complete'){add(tx('إرجاع إلى القبول','Return to acceptance'),()=>returnToAcceptance(id));if(['On Hold','Needs Review','Needs Update'].includes(r.status))add(tx('إرجاع للفني','Return to technician'),()=>returnToTech(id));}
 const field=(label,v)=>`<div><dt>${e(label)}</dt><dd>${e(v||'—')}</dd></div>`;
 const sections=[
 [tx('التفاصيل','Details'),()=>`<dl class="ad-detail-fields">${field(tx('العنوان','Title'),r.title)}${field(tx('المشروع','Project'),r.project)}${field(tx('الفني','Technician'),r.assignedTo)}${field(tx('مقدم الطلب','Requested by'),r.requestedBy)}${field(tx('الهاتف','Phone'),r.phone)}${field(tx('الأولوية','Priority'),dispPri(r.priority))}${field(tx('موعد الاستحقاق','Due date'),r.due)}${field(tx('ملاحظات','Notes'),r.notes)}</dl>`],
 [tx('الصور والملفات','Images & files'),()=>{const a=weAtt(r);const imgs=(list)=>list.map(url=>{const safe=AdvaconExperience.safeURL(url);return safe?`<a href="${e(safe)}" target="_blank" rel="noopener"><img src="${e(safe)}" alt="${e(tx('مرفق الطلب','Request attachment'))}" loading="lazy"></a>`:'';}).join('');const docs=(list)=>list.map(f=>{const safe=AdvaconExperience.safeURL(f.url);return safe?`<a class="btn sec" href="${e(safe)}" target="_blank" rel="noopener">${e(f.name||tx('مستند','Document'))}</a>`:'';}).join('');return `<h3>${tx('مرفقات البلاغ','Request attachments')}</h3><div class="ad-images">${imgs(a.ci)}</div>${docs(a.cd)}<h3>${tx('إثبات الإنجاز','Completion evidence')}</h3><div class="ad-images">${imgs(a.pi)}</div>${docs(a.pd)}<p>${e(r.closeoutNote||'')}</p>${!a.ci.length&&!a.pi.length&&!a.cd.length&&!a.pd.length?`<p class="empty">${tx('لا توجد مرفقات','No attachments')}</p>`:''}`;}],
 [tx('المواد','Materials'),()=>{const badge=state.mrBadges?.[String(id)];if(!badge)return `<p>${tx('لا يوجد طلب مواد متاح في البيانات الحالية.','No material request is available in the current data.')}</p>`;const status={pending:tx('بانتظار التجهيز','Pending preparation'),allocated:tx('مجهّز للاستلام','Ready for collection'),issued:tx('مصروف','Issued'),rejected:tx('مرفوض','Rejected'),cancelled:tx('ملغى','Cancelled')};return `<dl class="ad-detail-fields">${field(tx('حالة المواد','Material status'),status[badge.status]||badge.status)}${field(tx('عدد الأصناف','Line count'),String(badge.lines_count??'—'))}</dl><div class="btnrow">${mrProcBtn(id)}</div>`;}],
 [tx('سجل الحركة','Timeline'),()=>`<ol class="ad-timeline">${[[tx('استقبال الطلب','Received'),r.receivedAt||r.received],[tx('بدء العمل','Started'),r.startedAt],[tx('أُرسل للتأكيد','Submitted for confirmation'),r.pendingConfirmAt],[tx('اكتمال / إغلاق','Completed / closed'),r.confirmedAt||r.closed],[tx('رفض / إلغاء','Declined / cancelled'),r.rejectedAt]].filter(x=>x[1]).map(x=>`<li><b>${e(x[0])}</b><span>${e(wpDate(x[1]))}</span></li>`).join('')}</ol>`]
 ];
 sections.forEach(([label,content],i)=>{const b=document.createElement('button');b.textContent=label;b.type='button';b.setAttribute('role','tab');b.onclick=()=>{[...tabs.children].forEach(x=>x.setAttribute('aria-selected',String(x===b)));panel.innerHTML=content();const params=new URLSearchParams(location.hash.split('?')[1]||'');if(params.get('task')===String(id)){params.set('pane',String(i));history.replaceState(history.state,'',location.hash.split('?')[0]+'?'+params);}AdvaconUI.enhance(panel);};tabs.append(b);if(!i)b.click();});
 tabs.addEventListener('keydown',ev=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(ev.key))return;ev.preventDefault();const buttons=[...tabs.children],i=buttons.indexOf(document.activeElement),next=ev.key==='Home'?0:ev.key==='End'?buttons.length-1:(i+(ev.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();buttons[next].click();});
 panel.addEventListener('click',event=>{if(event.target.closest('button[onclick]')&&detail){detail.close();detail=null;}},true);
 tabs.children[initialTab]?.click();
 body.append(tabs,panel,actionbar);detail=AdvaconUI.modal({title:fmtID(id)+' · '+r.title,body,footer:false,onClose:()=>{detail=null;if(new URLSearchParams(location.hash.split('?')[1]||'').get('task')===String(id))history.replaceState(history.state,'',returnHash);}});detail.modal.classList.add('ad-detail-modal');
};
function decorate(){
 const admin=state.role==='admin';document.body.classList.toggle('ad-admin',admin);if(!admin)return;
 const activeRoute=['archive'].includes(state.route)?'all':['open','media'].includes(state.route)?'manage':state.route==='staffdir'?'staffdir':state.route;document.querySelectorAll('.side-nav button').forEach(b=>b.classList.toggle('active',b.getAttribute('onclick')===`go('${activeRoute}')`));
 const rename=(key,label)=>{const button=document.querySelector(`.side-nav [onclick="go('${key}')"]`);if(button?.children[1])button.children[1].textContent=label;};rename('dashboard',tx('الرئيسية','Home'));rename('reports',tx('التقارير والإحصاءات','Reports & statistics'));
 rename('all',tx('سجل الطلبات','Request register'));rename('manage',tx('الطلبات','Requests'));rename('techtasks',tx('الفريق','Team'));
 const statuses={'Overdue':'متأخرة','Not Started':'لم تبدأ','In Progress':'قيد التنفيذ','Complete':'مكتملة','Cancelled':'ملغاة','On Hold':'معلّقة','Needs Review':'بحاجة مراجعة','Needs Update':'بحاجة تحديث'};
 if(L==='ar')document.querySelectorAll('#view .st').forEach(b=>{if(statuses[b.textContent])b.textContent=statuses[b.textContent];});
 const nav=document.querySelector('.side-nav');if(nav){const groups=[['dashboard',tx('مساحة العمل','WORKSPACE')],['techtasks',tx('الفريق والأصول','Team & Assets')],['all',tx('السجلات والإعدادات','Records & Settings')]];groups.forEach(([key,label])=>{const b=nav.querySelector(`[onclick="go('${key}')"]`);if(b&&!b.previousElementSibling?.classList.contains('ad-nav-label')){const title=document.createElement('div');title.className='ad-nav-label';title.textContent=label;b.before(title);}});nav.querySelectorAll('button').forEach(b=>{if(b.classList.contains('active'))b.setAttribute('aria-current','page');});}
 if(state.route==='dashboard'){const target=document.getElementById('ad-decisions');if(target)renderDecisionSummary(target);}
 const query=new URLSearchParams(location.hash.split('?')[1]||'');if(!detail&&query.has('task')){const id=Number(query.get('task'));if(Number.isSafeInteger(id))adminDetail(id,Math.max(0,Math.min(3,Number(query.get('pane'))||0)));}

}
window.adminDecorate=decorate;
window.addEventListener('popstate',()=>{if(state.role==='admin'){const target=location.hash;adminCloseDetail();history.replaceState(history.state,'',target);state.route=adminResolveRoute(target.slice(1)||'dashboard');render();}});
document.addEventListener('DOMContentLoaded',decorate);
let lastClockSignature='';
window.adminRefreshClock=function(){if(state.role!=='admin'||!['manage','techtasks'].includes(state.route)||document.hidden||document.querySelector('.au-modal,.modal-bg')||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;const signature=state.requests.map(calc).filter(r=>r.schedStart||r.confirmedAt).map(r=>[r.id,r.isFuture,r.isReady,adminRecentlyDone(r),r.isFuture?Math.ceil((new Date(r.schedStart)-Date.now())/60000):''].join(':')).join('|');if(signature!==lastClockSignature){lastClockSignature=signature;render();}};
setInterval(()=>adminRefreshClock(),60000);
// Unified register and reporting: one filtered dataset for screen and downloads.
const registerDefaults={category:'',priority:'',from:'',to:'',dateBy:'received',sort:'newest',columns:'id,title,requester,project,category,assignee,status,received,accepted,closed,duration'};
Object.assign(work,registerDefaults);
const fieldNames=()=>({id:tx('رقم الطلب','Request ID'),title:tx('الطلب','Request'),requester:tx('مقدم الطلب','Requested by'),project:tx('المشروع / الرقم','Project / number'),category:tx('الفئة','Category'),priority:tx('الأولوية','Priority'),assignee:tx('الفني','Technician'),status:tx('الحالة','Status'),received:tx('الاستلام','Received'),accepted:tx('القبول / الإسناد','Accepted / assigned'),closed:tx('الإغلاق','Closed'),duration:tx('مدة الإنجاز','Completion time'),due:tx('الاستحقاق','Due')});
const dateNames=()=>({received:tx('تاريخ الاستلام','Received date'),accepted:tx('تاريخ القبول / الإسناد','Accepted / assigned date'),closed:tx('تاريخ الإغلاق','Closed date'),scheduled:tx('موعد البدء المجدول','Scheduled start'),rejected:tx('تاريخ الرفض / الإلغاء','Rejected / cancelled date')});
function dateValue(r,key){return key==='received'?r.receivedAt||r.received:key==='accepted'?r.startedAt:key==='closed'?r.confirmedAt:key==='scheduled'?r.schedStart:r.rejectedAt;}
function rangeMatch(value,from,to){if(!from&&!to)return true;if(!value)return false;const raw=String(value),ms=Date.parse(/^\d{4}-\d{2}-\d{2}$/.test(raw)?raw+'T00:00:00+03:00':raw);return Number.isFinite(ms)&&(!from||ms>=Date.parse(from+'T00:00:00+03:00'))&&(!to||ms<Date.parse(to+'T00:00:00+03:00')+86400000);}
function registryMatch(r){const q=work.q.trim().toLowerCase();return matches(r,work.stage)&&(!work.status||r.effStatus===work.status||r.status===work.status)&&(!work.project||r.project===work.project)&&(!work.assignee||r.assignedTo===work.assignee)&&(!work.category||r.category===work.category)&&(!work.priority||r.priority===work.priority)&&rangeMatch(dateValue(r,work.dateBy),work.from,work.to)&&[r.title,r.requestedBy,r.assignedTo,r.project,r.category,r.notes,fmtID(r.id)].join(' ').toLowerCase().includes(q);}
window.adminWorkRows=()=>state.requests.map(calc).filter(registryMatch).sort((a,b)=>work.sort==='oldest'?a.id-b.id:work.sort==='project'?String(a.project||'').localeCompare(String(b.project||''))||b.id-a.id:work.sort==='closed'?(Date.parse(b.confirmedAt)||0)-(Date.parse(a.confirmedAt)||0)||b.id-a.id:b.id-a.id);
function selectedColumns(){const names=fieldNames();return work.columns.split(',').filter((k,i,a)=>names[k]&&a.indexOf(k)===i);}
function cellValue(r,key){return ({id:fmtID(r.id),title:r.title,requester:r.requestedBy,project:r.project,category:dispCat(r.category),priority:dispPri(r.priority),assignee:r.assignedTo,status:r.status==='Rejected'?tx('مرفوض','Rejected'):r.pendingConfirm?tx('بانتظار التأكيد','Awaiting confirmation'):r.effStatus,received:fmtTime(r.receivedAt||r.received),accepted:fmtTime(r.startedAt),closed:fmtTime(r.confirmedAt),duration:fmtDuration(r.receivedAt,r.confirmedAt),due:r.due})[key]||'—';}
function registryTable(rows,interactive){const cols=selectedColumns(),names=fieldNames();return `<div class="tbl-wrap"><table class="tbl rep-tbl"><thead><tr>${cols.map(k=>`<th>${e(names[k])}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(k=>`<td>${interactive&&(k==='id'||k==='title')?`<button class="ad-title-button" data-request-id="${Number(r.id)}" onclick="adminDetail(${Number(r.id)})">${e(cellValue(r,k))}</button>`:e(cellValue(r,k))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function registryResults(){const rows=adminWorkRows(),max=Math.max(1,Math.ceil(rows.length/40));work.page=Math.min(work.page,max);return `<p role="status">${tx('عرض','Showing')} ${rows.length} ${tx('من أصل','of')} ${state.requests.length} · ${tx('صفحة','Page')} ${work.page}/${max}</p>${rows.length?registryTable(rows.slice((work.page-1)*40,work.page*40),true):`<div class="empty">${tx('لا توجد نتائج؛ عدّل الفلاتر أو وسّع الفترة.','No results; adjust filters or widen the period.')}</div>`}<div class="btnrow"><button class="btn sec" ${work.page<=1?'disabled':''} onclick="adminSetWork('page',${work.page-1})">${tx('السابق','Previous')}</button><button class="btn sec" ${work.page>=max?'disabled':''} onclick="adminSetWork('page',${work.page+1})">${tx('التالي','Next')}</button></div>`;}
const uniqueValues=field=>[...new Set(state.requests.map(r=>r[field]).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b)));
function selectFilter(key,label,values,value){return `<label>${e(label)}<select onchange="adminRegisterSet('${key}',this.value)"><option value="">${tx('الكل','All')}</option>${values.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${e(v)}" ${value===v?'selected':''}>${e(l)}</option>`;}).join('')}</select></label>`;}
window.adminRegisterSet=function(key,value){if(key==='stage'&&!value)value='all';if((key==='from'&&value&&work.to&&value>work.to)||(key==='to'&&value&&work.from&&value<work.from)){toast(tx('تاريخ البداية يجب ألا يتجاوز النهاية','Start date must not exceed end date'));render();return;}adminSetWork(key,value);};
window.adminRegisterReset=function(){Object.assign(work,registerDefaults,{q:'',project:'',assignee:'',status:'',stage:'all',layout:'table',page:1});history.replaceState(null,'','#all');render();};
window.adminRegisterColumn=function(key,on){const cols=selectedColumns().filter(k=>k!==key);if(on)cols.push(key);if(!cols.length){toast(tx('اختر عمودًا واحدًا على الأقل','Select at least one column'));render();return;}adminSetWork('columns',cols.join(','));};
window.adminRegisterPeriod=function(value){let from='',to='';if(value!=='all'){to=today();const d=new Date(to+'T12:00:00+03:00');d.setUTCDate(d.getUTCDate()-(value==='week'?6:value==='month'?29:0));from=d.toISOString().slice(0,10);}Object.assign(work,{from,to,page:1});adminSetWork('from',from);};
function filterSummary(){return [work.q?tx('بحث: ','Search: ')+work.q:'',work.stage!=='all'?Object.fromEntries(stages())[work.stage]:'',work.status,work.project,work.category?dispCat(work.category):'',work.priority?dispPri(work.priority):'',work.assignee,dateNames()[work.dateBy]+': '+(work.from||tx('البداية','Beginning'))+' — '+(work.to||tx('الآن','Now')),tx('الترتيب: ','Sort: ')+({newest:tx('الأحدث','Newest'),oldest:tx('الأقدم','Oldest'),project:tx('المشروع','Project'),closed:tx('آخر إغلاق','Latest closure')})[work.sort]].filter(Boolean).join(' · ');}
window.adminRegistryView=function(){work.layout='table';const advanced=!!(work.project||work.category||work.priority||work.assignee||work.status||work.from||work.to||work.stage!=='all');return `<div class="phead"><h1>${tx('سجل الطلبات','Request register')}</h1><p>${tx('الأرشيف الشامل والتقارير حسب اختياراتك. جميع الحالات المحفوظة متاحة هنا.','Complete archive and reports matching your choices. All retained statuses are available here.')}</p></div><div class="register-tools"><label>${tx('بحث','Search')}<input type="search" value="${e(work.q)}" placeholder="${tx('رقم الطلب، المشروع، العنوان، مقدم الطلب أو الفني','Request ID, project, title, requester or technician')}" oninput="adminWorkSearch(this)"></label><button class="btn sec" onclick="adminRegisterExport('xlsx')">Excel</button><button class="btn sec" onclick="adminRegisterExport('pdf')">PDF</button></div><details class="register-filters" ${advanced?'open':''}><summary>${tx('الفلاتر والفترة','Filters & period')}</summary><div class="register-filter-grid">${selectFilter('status',tx('الحالة','Status'),uniqueValues('status').concat(['Overdue']).filter((x,i,a)=>a.indexOf(x)===i),work.status)}${selectFilter('stage',tx('مرحلة الطلب','Request stage'),stages().filter(([k])=>k!=='all'),work.stage)}<label>${tx('المشروع بالاسم أو الرقم','Project name or number')}<input list="register-projects" value="${e(work.project)}" onchange="adminRegisterSet('project',this.value)"><datalist id="register-projects">${uniqueValues('project').map(v=>`<option value="${e(v)}"></option>`).join('')}</datalist></label>${selectFilter('category',tx('الفئة / نوع الصيانة','Category / maintenance type'),uniqueValues('category').map(v=>[v,dispCat(v)]),work.category)}${selectFilter('priority',tx('الأولوية','Priority'),uniqueValues('priority').map(v=>[v,dispPri(v)]),work.priority)}${selectFilter('assignee',tx('الفني','Technician'),uniqueValues('assignedTo'),work.assignee)}<label>${tx('نوع التاريخ','Date basis')}<select onchange="adminRegisterSet('dateBy',this.value)">${Object.entries(dateNames()).map(([v,l])=>`<option value="${v}" ${work.dateBy===v?'selected':''}>${l}</option>`).join('')}</select></label><label>${tx('من','From')}<input type="date" value="${e(work.from)}" onchange="adminRegisterSet('from',this.value)"></label><label>${tx('إلى','To')}<input type="date" value="${e(work.to)}" onchange="adminRegisterSet('to',this.value)"></label><label>${tx('الترتيب','Sort')}<select onchange="adminRegisterSet('sort',this.value)">${[['newest',tx('الأحدث','Newest')],['oldest',tx('الأقدم','Oldest')],['project',tx('المشروع','Project')],['closed',tx('آخر إغلاق','Latest closure')]].map(([v,l])=>`<option value="${v}" ${work.sort===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="btnrow">${[['today',tx('اليوم','Today')],['week',tx('آخر 7 أيام','Last 7 days')],['month',tx('آخر 30 يومًا','Last 30 days')],['all',tx('كل الفترة','All time')]].map(([v,l])=>`<button class="btn sec sm" onclick="adminRegisterPeriod('${v}')">${l}</button>`).join('')}<button class="btn sec" onclick="adminRegisterReset()">${tx('مسح الفلاتر','Reset filters')}</button></div></details><details class="register-columns"><summary>${tx('الأعمدة الظاهرة وفي التقرير','Screen & report columns')}</summary><div class="register-column-options">${Object.entries(fieldNames()).map(([k,l])=>`<label><input type="checkbox" ${selectedColumns().includes(k)?'checked':''} onchange="adminRegisterColumn('${k}',this.checked)">${l}</label>`).join('')}</div></details><div id="register-active">${activeFilters()}</div><div id="ad-work-results">${registryResults()}</div>`;};
function activeFilters(){return `<div class="register-chips">${['q','project','category','priority','assignee','status','from','to'].filter(k=>work[k]).map(k=>`<button class="btn sec sm" onclick="adminRegisterSet('${k}','')">${e(({q:tx('بحث','Search'),from:tx('من','From'),to:tx('إلى','To'),...fieldNames()})[k]||tx('الفني','Technician'))}: ${e(work[k])} ×</button>`).join('')}${work.stage!=='all'?`<button class="btn sec sm" onclick="adminRegisterSet('stage','all')">${e(Object.fromEntries(stages())[work.stage])} ×</button>`:''}</div>`;}
window.adminWorkSearch=function(input){work.q=input.value;work.page=1;document.getElementById('ad-work-results').innerHTML=registryResults();document.getElementById('register-active').innerHTML=activeFilters();};
window.adminRegisterExport=async function(kind){const rows=adminWorkRows(),cols=selectedColumns(),names=fieldNames(),summary=filterSummary();if(!rows.length){toast(tx('لا توجد نتائج للتصدير','No results to export'));return;}if(kind==='pdf'){openReportWindow(repShell(tx('تقرير سجل الطلبات','Request register report'),summary,kpi(rows.length,tx('طلبات مطابقة','Matching requests')),registryTable(rows,false)).replace('<html>','<html dir="'+(L==='ar'?'rtl':'ltr')+'">').replace('</style>','@page{size:landscape} th,td{text-align:start;overflow-wrap:anywhere} </style>'));return;}try{const XLSX=await loadSheetJS(),wb=XLSX.utils.book_new();const data=[cols.map(k=>names[k]),...rows.map(r=>cols.map(k=>cellValue(r,k)))];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(data),'Requests');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([[tx('الفلاتر','Filters'),summary],[tx('العدد','Count'),rows.length],[tx('وقت التصدير','Exported at'),fmtTime(nowTs())]]),'Selection');await AdvaconReports.excel(wb,'ADVACON_Register_'+today()+'.xlsx');}catch(err){toast(tx('تعذر تصدير Excel؛ أعد المحاولة','Excel export failed; retry'));}};
const analytics={tab:'trend',from:'',to:'',project:'',category:'',assignee:'',grain:'month',dimension:'project'};
window.adminAnalyticsSet=function(key,value){if((key==='from'&&value&&analytics.to&&value>analytics.to)||(key==='to'&&value&&analytics.from&&value<analytics.from)){toast(tx('راجع بداية الفترة ونهايتها','Check the period dates'));render();return;}analytics[key]=value;render();};
function analyticsBase(){return state.requests.map(calc).filter(r=>(!analytics.project||r.project===analytics.project)&&(!analytics.category||r.category===analytics.category)&&(!analytics.assignee||r.assignedTo===analytics.assignee));}
window.adminAnalyticsOpen=function(field,value,dateBy='received'){Object.assign(work,registerDefaults,{q:'',stage:'all',status:'',project:analytics.project,category:analytics.category,assignee:analytics.assignee,from:analytics.tab==='team'?'':analytics.from,to:analytics.tab==='team'?'':analytics.to,dateBy,page:1,layout:'table'});if(field)work[field]=decodeURIComponent(value);if(analytics.tab==='team')work.stage='assigned';go(workHash());};
function analyticsBars(rows,field,label){const groups=new Map();rows.forEach(r=>{const k=r[field]||'';if(k)groups.set(k,(groups.get(k)||0)+1);});const sorted=[...groups].sort((a,b)=>b[1]-a[1]),max=Math.max(1,...sorted.map(x=>x[1]));return `<h3>${label}</h3>${sorted.length?sorted.map(([key,n])=>`<button class="analytics-bar" onclick="adminAnalyticsOpen('${field==='assignedTo'?'assignee':field}','${encodeURIComponent(key).replace(/'/g,'%27')}')"><span>${e(field==='category'?dispCat(key):key)}</span><span class="analytics-track"><i style="width:${n/max*100}%"></i></span><b>${n}</b></button>`).join(''):`<p class="empty">${tx('لا توجد بيانات','No data')}</p>`}`;}
function analyticsTrend(rows){const bucket=value=>{if(!value)return null;const ms=Date.parse(value);if(!Number.isFinite(ms))return null;const d=new Date(ms+10800000);if(analytics.grain==='month')return d.toISOString().slice(0,7);if(analytics.grain==='week')d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10);};const counts=new Map();for(const r of rows)for(const [field,idx] of [['received',0],['closed',1]]){const v=dateValue(r,field);if(!rangeMatch(v,analytics.from,analytics.to))continue;const key=bucket(v);if(key){if(!counts.has(key))counts.set(key,[0,0]);counts.get(key)[idx]++;}}const keys=[...counts.keys()].sort(),max=Math.max(1,...[...counts.values()].flat());return `<p>${tx('الوارد حسب تاريخ الاستلام، والمنجز حسب تاريخ الإغلاق. الفترات بلا أحداث لا تظهر.','Received by receipt date; completed by closure date. Periods without events are omitted.')}</p><div class="analytics-legend"><span>● ${tx('الوارد','Received')}</span><span>● ${tx('المنجز','Completed')}</span></div><div class="analytics-trend">${keys.length?keys.map(k=>`<div class="analytics-pair"><b>${e(k)}</b>${counts.get(k).map((n,i)=>`<div class="analytics-track ${i?'closed':''}" title="${n}"><i style="width:${n/max*100}%"></i><span>${n}</span></div>`).join('')}</div>`).join(''):`<p class="empty">${tx('لا توجد بيانات','No data')}</p>`}</div>`;}
window.adminReportsView=function(){const base=analyticsBase(),period=base.filter(r=>rangeMatch(dateValue(r,'received'),analytics.from,analytics.to)),current=base.filter(r=>live(r)&&isOpen(r)),W=state.widgets;const filter=(key,label,values)=>`<label>${label}<select onchange="adminAnalyticsSet('${key}',this.value)"><option value="">${tx('الكل','All')}</option>${values.map(v=>`<option value="${e(v)}" ${analytics[key]===v?'selected':''}>${e(key==='category'?dispCat(v):v)}</option>`).join('')}</select></label>`;let body='';if(analytics.tab==='trend')body=W.overTime?`<label>${tx('تجميع الزمن','Time grouping')}<select onchange="adminAnalyticsSet('grain',this.value)">${[['day',tx('يومي','Daily')],['week',tx('أسبوعي','Weekly')],['month',tx('شهري','Monthly')]].map(([v,l])=>`<option value="${v}" ${analytics.grain===v?'selected':''}>${l}</option>`).join('')}</select></label>${analyticsTrend(base)}`:'';else if(analytics.tab==='projects'){const key=analytics.dimension==='project'?'byProj':'byCat';body=`<div class="btnrow"><button class="btn sec" onclick="adminAnalyticsSet('dimension','project')">${tx('حسب المشروع','By project')}</button><button class="btn sec" onclick="adminAnalyticsSet('dimension','category')">${tx('حسب الفئة','By category')}</button></div><p>${tx('طلبات استُلمت خلال الفترة المختارة','Requests received during the selected period')}</p>`+(W[key]?analyticsBars(period,analytics.dimension,tx('توزيع الطلبات','Request distribution')):tx('هذا الرسم مخفي من الإعدادات','This chart is hidden in settings'));}else{body=`<p>${tx('لقطة للعمل القائم الآن؛ فترة الاستلام لا تطبق هنا حتى لا تخفي المهام القديمة. فلاتر المشروع والفئة والفني مطبقة.','Current workload snapshot; receipt dates do not apply here so older tasks remain visible. Project, category and technician filters apply.')}</p>`;if(W.wlTeam)body+=analyticsBars(current,'assignedTo',tx('المهام القائمة حسب الفني','Current tasks by technician'));if(W.alerts){const late=current.filter(r=>r.effStatus==='Overdue');body+=`<h3>${tx('عمر التأخير الحالي','Current overdue age')}</h3><div class="analytics-age">${[[1,3],[4,7],[8,Infinity]].map(([min,max])=>`<div><strong>${late.filter(r=>-r.daysleft>=min&&-r.daysleft<=max).length}</strong><span>${max===Infinity?tx('أكثر من 7 أيام','More than 7 days'):min+'–'+max+' '+tx('أيام','days')}</span></div>`).join('')}</div>`;}}return `<div class="phead"><h1>${tx('التقارير والإحصائيات','Reports & Statistics')}</h1></div>${dailyDashboard()}<section class="panel panel-pad analytics-panel"><h2>${tx('الإحصائيات','Statistics')}</h2><div class="ad-tabs">${[['trend',tx('حركة الطلبات','Request trends')],['projects',tx('المشاريع والفئات','Projects & categories')],['team',tx('الفريق والتأخير','Team & delays')]].map(([v,l])=>`<button aria-selected="${analytics.tab===v}" onclick="adminAnalyticsSet('tab','${v}')">${l}</button>`).join('')}</div><details class="register-filters"><summary>${tx('فلاتر الإحصائيات — مستقلة عن لوحة اليوم','Statistics filters — separate from today’s dashboard')}</summary><div class="register-filter-grid"><label>${tx('من','From')}<input type="date" value="${e(analytics.from)}" ${analytics.tab==='team'?'disabled':''} onchange="adminAnalyticsSet('from',this.value)"></label><label>${tx('إلى','To')}<input type="date" value="${e(analytics.to)}" ${analytics.tab==='team'?'disabled':''} onchange="adminAnalyticsSet('to',this.value)"></label>${filter('project',tx('المشروع / الرقم','Project / number'),uniqueValues('project'))}${filter('category',tx('الفئة','Category'),uniqueValues('category'))}${filter('assignee',tx('الفني','Technician'),uniqueValues('assignedTo'))}</div><button class="btn sec" onclick="adminAnalyticsReset()">${tx('مسح الفلاتر','Reset filters')}</button></details><p class="ad-muted">${e([analytics.tab==='team'?tx('العمل القائم الآن','Current work'):(analytics.from||tx('البداية','Beginning'))+' — '+(analytics.to||tx('الآن','Now')),analytics.project,analytics.category,analytics.assignee].filter(Boolean).join(' · '))}</p><div class="analytics-content">${body||tx('الرسم مخفي؛ يمكنك إظهاره من الإعدادات.','Chart hidden; enable it in Settings.')}</div></section>`;};
window.adminAnalyticsReset=()=>{Object.assign(analytics,{from:'',to:'',project:'',category:'',assignee:''});render();};

})();

